export const COLOR_FIELDS = {
 amount:['Mức áp dụng',0,100,1], strength:['Đổi sang màu đã chọn',0,100,1], objectExposure:['Độ sáng vùng chọn',-2,2,.05], shading:['Giữ nếp & sắc độ',20,140,1], saturation:['Độ rực màu',0,150,1], grow:['Nới / thu viền (px)',-12,12,1], feather:['Mềm viền (px)',0,8,1], exposure:['Sáng toàn ảnh',-2,2,.05], temperature:['Ấm / lạnh',-50,50,1], contrast:['Độ sâu tương phản',-40,60,1], blur:['Mờ hậu cảnh',0,80,1], bokeh:['Bokeh hậu cảnh',0,100,1], sun:['Nắng phía sau',0,100,1], sunX:['Vị trí nắng ngang',0,100,1], sunY:['Vị trí nắng dọc',0,100,1], shadow:['Bóng tiếp xúc',0,100,1], inkThreshold:['Độ nhạy tìm mực tối',10,90,1], inkGrow:['Nới nét mực (px)',0,10,1]
};
export const COLOR_DEFAULTS={amount:100,strength:100,objectExposure:0,shading:100,saturation:100,grow:0,feather:1,exposure:0,temperature:0,contrast:0,blur:0,bokeh:0,sun:0,sunX:78,sunY:15,shadow:0,inkThreshold:52,inkGrow:2,color:'#263b62',scene:false,protectWhite:true,useClean:true,closePrint:true,background:'original'};
