export const BEVERAGE_PRESETS=[{id:'natural',name:'Trong trẻo',note:'Màu gốc · sáng nhẹ',params:{background:'original',exposure:.2,contrast:8,blur:10,bokeh:0,sun:0,shadow:0,temperature:0}},{id:'studio',name:'Studio kem',note:'Nền đồ họa · bóng mềm',params:{background:'cream',exposure:.18,contrast:10,blur:0,bokeh:0,sun:0,shadow:28,temperature:2}},{id:'garden',name:'Vườn bokeh',note:'Nền xanh đồ họa',params:{background:'sage',exposure:.2,contrast:10,blur:0,bokeh:35,sun:12,shadow:15,temperature:0}},{id:'golden',name:'Nắng chiều',note:'Ánh ấm · hậu cảnh gốc',params:{background:'original',exposure:.25,contrast:9,blur:25,bokeh:22,sun:32,shadow:0,temperature:8}}];
export function colorDefaults(mode='garment'){return mode==='beverage'?{...COLOR_DEFAULTS,strength:0,color:'#edae36',scene:true,protectWhite:true,exposure:.2,contrast:8,blur:10}: {...COLOR_DEFAULTS};}
export function colorParams(input={}){const p={...COLOR_DEFAULTS,...input};for(const [k,v]of Object.entries(input)){if(k in COLOR_FIELDS){const[,min,max]=COLOR_FIELDS[k];if(!Number.isFinite(v)||v<min||v>max)throw Error('Thông số màu không hợp lệ: '+k);}else if(['scene','protectWhite','useClean','closePrint'].includes(k)){if(typeof v!=='boolean')throw Error('Invalid color option.');}else if(k==='color'){if(typeof v!=='string'||!/^#[0-9a-f]{6}$/i.test(v))throw Error('Invalid color.');}else if(k==='background'){if(!['original','cream','sage','sunset','custom'].includes(v))throw Error('Invalid background.');}else throw Error('Unknown color parameter.');}return p;}
